222	    /// <summary>The canonical DSL for a rules table: all 16 cases, alternates joined by <c>|</c> —
223	    /// the exact grammar <see cref="TileGridBaking.ParseRules"/> reads.</summary>
224	    public static string SerializeRules(Point[][] table)
225	    {
226	        var sb = new StringBuilder();
227	        for (var mask = 0; mask < 16; mask++)
228	        {
229	            if (mask > 0) sb.Append(' ');
230	            sb.Append(mask).Append(':');
231	            var alternates = table[mask] is { Length: > 0 } a ? a : new[] { Point.Zero };
232	            for (var i = 0; i < alternates.Length; i++)
233	            {
234	                if (i > 0) sb.Append('|');
235	                sb.Append(alternates[i].X).Append(',').Append(alternates[i].Y);
236	            }
237	        }
238	        return sb.ToString();
239	    }
