504	    private void BuildChrome()
505	    {
506	        _surface = CreateFill(EditorTheme.Bg0, EditorTheme.Bg0, EditorTheme.Depths.DialogBackdrop);
507	        _leftPaneFill = CreateFill(EditorTheme.Bg1, EditorTheme.Border, EditorTheme.Depths.DialogPanel);
508	        _leftHeader = CreateLabel();
509	        _casesTitle = CreateLabel();
510	        _tilesetHeader = CreateLabel();
511	        _tilesetKeyLabel = CreateLabel();
512	        _tileSizeLabel = CreateLabel();
513	        _emptyLabel = CreateLabel();
514	        (_modeButton, _modeLabel) = CreateButton();
515	        (_changeButton, _changeLabel) = CreateButton();
516	
517	        for (var i = 0; i < ListPool; i++)
518	        {
519	            _listBgs.Add(CreateMesh(EditorTheme.Depths.DialogPanel + 0.01f));
520	            _listSwatches.Add(CreateFill(Color.White, EditorTheme.Border, EditorTheme.Depths.DialogControl));
521	            _listLabels.Add(CreateLabel());
522	        }
523	        for (var mask = 0; mask < 16; mask++)
524	        {
525	            var (button, _) = CreateButton(withLabel: false);
526	            _caseButtons.Add(button);
527	            _caseGlyphs.Add(CreateMesh(EditorTheme.Depths.DialogControl + 0.002f));
528	            for (var t = 0; t < MaxAlternatesShown; t++)
529	                _caseThumbs.Add(CreateThumb());
530	        }
531	        for (var i = 0; i < 200; i++)
532	            _sheetButtons.Add(CreateThumb());
533	        for (var i = 0; i < DslLines; i++)
534	            _dslLineLabels.Add(CreateLabel());
535	        _built = true;
536	    }
537	
538	    private void LayoutChrome(Rectangle surface, List<ListRow> rows, float scale)
539	    {
540	        var labelH = (_font?.LineHeight ?? 48f) * EditorChromeBuilder.LabelScale * scale;
541	        var leftPane = LeftPaneRect(surface, scale);
542	        var center = CenterRect(surface, scale);
543	        var rightPane = RightPaneRect(surface, scale);
544	
545	        Place(_surface, surface.X, surface.Y);
546	        SetButtonVisual(_surface, surface.Width, surface.Height, EditorTheme.Bg0, EditorTheme.Bg0);
547	        Place(_leftPaneFill, leftPane.X, leftPane.Y);
548	        SetButtonVisual(_leftPaneFill, leftPane.Width, leftPane.Height, EditorTheme.Bg1, EditorTheme.Border);
549	
550	        PlaceLabel(_leftHeader, "RULE SETS", leftPane.X + Px(Pad, scale), leftPane.Y + Px(Pad, scale), scale,
551	            EditorTheme.Text1);
552	
553	        LayoutList(leftPane, rows, labelH, scale);
554	
555	        var value = CurrentValue();
556	        if (value == null || !_layer.IsAlive)
557	        {
558	            // Empty state: no rule set anywhere. The list already shows the hint row; park the panes.
559	            ParkCasesAndSheet();
560	            Park(_modeButton); Park(_modeLabel);
561	            Park(_changeButton); Park(_changeLabel);
562	            Park(_tilesetHeader); Park(_tilesetKeyLabel); Park(_tileSizeLabel);
563	            foreach (var line in _dslLineLabels) Park(line);
564	            PlaceLabel(_emptyLabel, "Select or create a rule set on an Indexed Layer",
565	                center.X, center.Y + Px(HeaderH, scale), scale, EditorTheme.TextMuted);
