718	    /// <summary>The 3×3 neighborhood glyph for <paramref name="mask"/>: center = Accent; the four
719	    /// edge cells filled when that neighbor is SAME (bit set), hollow-dark when different; corners
720	    /// inert. The visual reading of "6:0,0" — right+down same, top+left exposed.</summary>
721	    private void SetGlyphMesh(Entity mesh, int mask, Rectangle box)
722	    {
723	        var vertices = new List<VertexPositionColor>();
724	        var indices = new List<int>();
725	        var offset = 0;
726	        var cw = box.Width / 3;
727	        void Cell(int cx, int cy, Color color)
728	        {
729	            var r = new Rectangle(box.X + cx * cw, box.Y + cy * cw, cw - 1, cw - 1);
730	            vertices.Add(new VertexPositionColor(new Vector3(r.Left, r.Top, 0), color));
731	            vertices.Add(new VertexPositionColor(new Vector3(r.Right, r.Top, 0), color));
732	            vertices.Add(new VertexPositionColor(new Vector3(r.Right, r.Bottom, 0), color));
733	            vertices.Add(new VertexPositionColor(new Vector3(r.Left, r.Bottom, 0), color));
734	            indices.Add(offset); indices.Add(offset + 1); indices.Add(offset + 2);
735	            indices.Add(offset); indices.Add(offset + 2); indices.Add(offset + 3);
736	            offset += 4;
737	        }
738	
739	        var same = EditorTheme.Text1;
740	        var different = EditorTheme.Bg4;
741	        Cell(1, 1, EditorTheme.Accent);
742	        Cell(1, 0, (mask & TileGridBaking.MaskUp) != 0 ? same : different);
743	        Cell(2, 1, (mask & TileGridBaking.MaskRight) != 0 ? same : different);
744	        Cell(1, 2, (mask & TileGridBaking.MaskDown) != 0 ? same : different);
745	        Cell(0, 1, (mask & TileGridBaking.MaskLeft) != 0 ? same : different);
746	
747	        var draw = mesh.Get<DrawComponent>();
748	        draw.Vertices = vertices.ToArray();
749	        draw.Indices = indices.ToArray();
750	        draw.PrimitiveType = PrimitiveType.TriangleList;
751	    }
